import{_ as r,o as t,c as n,ah as o}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Conservation","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/gestion-documentaire/conservation.md","filePath":"src/guide/gestion-documentaire/conservation.md"}'),s={name:"guide/gestion-documentaire/conservation.md"};function a(i,e,u,d,c,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="conservation" tabindex="-1">Conservation <a class="header-anchor" href="#conservation" aria-label="Permalink to &quot;Conservation&quot;">​</a></h1><p>Chaque type de document a une <strong>durée de conservation</strong>, réglée dans les <a href="/era-guide/guide/gestion-documentaire/types-de-documents.html">Types de documents</a>. Une fois cette durée écoulée, ERA <strong>archive</strong> le document de lui-même. Il ne le <strong>détruit jamais</strong> de lui-même : la destruction est proposée, puis approuvée par un administrateur.</p><h2 id="quand-un-document-est-archive" tabindex="-1">Quand un document est archivé <a class="header-anchor" href="#quand-un-document-est-archive" aria-label="Permalink to &quot;Quand un document est archivé&quot;">​</a></h2><p>La durée se compte à partir de la <strong>date du document</strong> (celle qu&#39;il porte), ou, à défaut, du jour où il a été déposé. Par exemple, un dossier d&#39;inscription daté du 2 septembre 2019 et conservé 5 ans est archivé à partir du 2 septembre 2024.</p><p>ERA vérifie chaque nuit les documents à archiver. Ne sont archivés que les documents <strong>validés</strong> ou <strong>rejetés</strong> : un document qui attend encore sa vérification reste où il est. Un type sans durée de conservation garde ses documents sans limite.</p><p>Un document archivé reste dans son dossier, avec l&#39;étiquette <strong>Archivé</strong> : on l&#39;ouvre comme avant. En revanche, il ne peut plus être supprimé par le bouton <strong>Supprimer</strong>, même par un administrateur : il ne quitte le dossier que par une destruction approuvée.</p><h2 id="l-ecran-conservation" tabindex="-1">L&#39;écran Conservation <a class="header-anchor" href="#l-ecran-conservation" aria-label="Permalink to &quot;L&#39;écran Conservation&quot;">​</a></h2><p>L&#39;écran <strong>Documents</strong> → <strong>Conservation</strong> est réservé à un administrateur et au gestionnaire documentaire. Il présente :</p><ul><li>combien de documents seront archivés dans les <strong>90 prochains jours</strong> ;</li><li>la liste <strong>Destruction proposée</strong> : les documents dont quelqu&#39;un a proposé la destruction, avec son nom et la date ;</li><li>la liste <strong>Archivés</strong> : les documents archivés, dont personne n&#39;a encore proposé la destruction.</li></ul><p>Chaque ligne indique le type, la personne concernée, et propose <strong>Ouvrir</strong> pour relire le document avant de décider.</p><h2 id="proposer-une-destruction" tabindex="-1">Proposer une destruction <a class="header-anchor" href="#proposer-une-destruction" aria-label="Permalink to &quot;Proposer une destruction&quot;">​</a></h2><ol><li>Dans <strong>Archivés</strong>, cochez les documents à détruire, ou <strong>Tout sélectionner</strong>.</li><li>Cliquez sur <strong>Proposer la destruction</strong>.</li></ol><p>Les documents passent dans <strong>Destruction proposée</strong>, avec l&#39;étiquette du même nom dans leur dossier. Le tableau de bord des administrateurs rappelle combien de destructions attendent leur approbation.</p><h2 id="approuver-ou-refuser-une-destruction" tabindex="-1">Approuver ou refuser une destruction <a class="header-anchor" href="#approuver-ou-refuser-une-destruction" aria-label="Permalink to &quot;Approuver ou refuser une destruction&quot;">​</a></h2><p>Seul un administrateur approuve une destruction.</p><ol><li>Dans <strong>Destruction proposée</strong>, cochez les documents.</li><li>Cliquez sur <strong>Détruire</strong>, puis confirmez. Les documents et leurs fichiers sont supprimés définitivement.</li></ol><p>Pour refuser, cliquez sur <strong>Garder</strong> : les documents restent archivés, et peuvent être proposés de nouveau plus tard. Le gestionnaire documentaire peut aussi retirer ainsi une proposition qu&#39;il a faite.</p><p>Chaque étape (archivage, proposition, destruction, refus) est inscrite au <a href="/era-guide/guide/admin/demo-et-journal.html">journal d&#39;activité</a>, avec la personne qui l&#39;a faite.</p>',18)])])}const g=r(s,[["render",a]]);export{m as __pageData,g as default};
